import React, { Component } from 'react';
import { Card, Table, Icon, Button, Spin, Alert, Input, Dropdown, Menu, Modal, message } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Search } = Input;

class ProgramsHierarchyList extends Component {
    constructor(props) {
        super(props);
        this.state = {
            programs: [], // Level 3 organization units (programs)
            loading: false,
            error: null,
            searchValue: '',
            filteredPrograms: [],
            deletingProgramId: null, // Track which program is being deleted
            selectedProgramIds: [], // Track selected programs for bulk operations
            isDeleting: false, // Track bulk delete operation
            refreshing: false, // Track refresh operation
            deleteProgress: {
                show: false,
                currentStep: '',
                currentProgram: '',
                completed: 0,
                total: 0,
                details: []
            }
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchPrograms();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchPrograms = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                level: 3,
                paging: false,
                fields: 'id,displayName,openingDate,parent[id,displayName,parent[id,displayName]]'
            });

            if (this._isMounted) {
                this.setState({
                    programs: data.organisationUnits || [],
                    filteredPrograms: data.organisationUnits || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching programs:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch programs. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleProgramEdit = (program) => {
        // Navigate to custom edit program page
        const redirectUrl = `/sims-web-maintenance/#/edit-program/${program.id}`;
        window.location.href = redirectUrl;
    };

    handleProgramDelete = (program) => {
        Modal.confirm({
            title: 'Delete Program',
            content: (
                <div>
                    <p>Are you sure you want to delete the program <strong>"{program.displayName}"</strong>?</p>
                    <p style={{ color: '#ff4d4f', marginBottom: 0 }}>This action will also delete all associated projects. This cannot be undone.</p>
                </div>
            ),
            okText: 'Delete',
            okType: 'danger',
            cancelText: 'Cancel',
            width: 450,
            onOk: () => {
                return this.deleteProgram(program.id);
            },
        });
    };

    deleteProgram = async (programId) => {
        this.setState({ deletingProgramId: programId });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            await api.delete(`organisationUnits/${programId}`);

            // Remove the deleted program from state
            const updatedPrograms = this.state.programs.filter(program => program.id !== programId);
            const updatedFilteredPrograms = this.state.filteredPrograms.filter(program => program.id !== programId);

            this.setState({
                programs: updatedPrograms,
                filteredPrograms: updatedFilteredPrograms,
                deletingProgramId: null
            });

            message.success('Program deleted successfully');
        } catch (error) {
            console.error('Error deleting program:', error);
            this.setState({ deletingProgramId: null });

            Modal.error({
                title: 'Delete Failed',
                content: `Failed to delete the program: ${error.message}`,
            });
        }
    };

    handleCreateProgram = () => {
        // Navigate to create new program page
        const redirectUrl = `/sims-web-maintenance/#/create-program`;
        window.location.href = redirectUrl;
    };

    // Get more actions menu for programs
    getProgramActionsMenu = (program) => {
        const { deletingProgramId } = this.state;
        const isDeleting = deletingProgramId === program.id;

        return (
            <Menu>
                <Menu.Item key="edit" onClick={() => this.handleProgramEdit(program)}>
                    <Icon type="edit" style={{ marginRight: '8px' }} />
                    Edit Program
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item
                    key="delete"
                    onClick={() => this.handleProgramDelete(program)}
                    disabled={isDeleting}
                    style={{ color: isDeleting ? '#ccc' : '#ff4d4f' }}
                >
                    <Icon type={isDeleting ? "loading" : "delete"} style={{ marginRight: '8px' }} />
                    {isDeleting ? 'Deleting...' : 'Delete Program'}
                </Menu.Item>
            </Menu>
        );
    };

    handleRefresh = async () => {
        this.setState({ refreshing: true });
        try {
            await this.fetchPrograms();
            this.setState({ 
                searchValue: '',
                selectedProgramIds: [],
                refreshing: false
            });
            message.success('Programs refreshed successfully');
        } catch (error) {
            console.error('Error refreshing programs:', error);
            this.setState({ refreshing: false });
            message.error('Failed to refresh programs');
        }
    };

    handleRowSelection = (selectedRowKeys) => {
        this.setState({ selectedProgramIds: selectedRowKeys });
    };

    handleSelectAll = () => {
        const { programs, searchValue, filteredPrograms } = this.state;
        const dataSource = searchValue ? filteredPrograms : programs;
        const allIds = dataSource.map(program => program.id);
        this.setState({ selectedProgramIds: allIds });
    };

    handleClearSelection = () => {
        this.setState({ selectedProgramIds: [] });
    };

    updateDeleteProgress = (updates) => {
        this.setState(prevState => ({
            deleteProgress: {
                ...prevState.deleteProgress,
                ...updates
            }
        }));
    };

    addProgressDetail = (detail) => {
        this.setState(prevState => ({
            deleteProgress: {
                ...prevState.deleteProgress,
                details: [...prevState.deleteProgress.details, `${new Date().toLocaleTimeString()}: ${detail}`]
            }
        }));
    };

    handleBulkDelete = () => {
        const { selectedProgramIds, programs } = this.state;
        const selectedPrograms = programs.filter(p => selectedProgramIds.includes(p.id));

        Modal.confirm({
            title: 'Delete Selected Programs',
            content: (
                <div>
                    <p>Are you sure you want to delete <strong>{selectedProgramIds.length} selected program(s)</strong>?</p>
                    <div style={{ maxHeight: '150px', overflowY: 'auto', marginBottom: '15px' }}>
                        {selectedPrograms.map(program => (
                            <div key={program.id} style={{ padding: '2px 0', fontSize: '12px' }}>
                                • {program.displayName}
                            </div>
                        ))}
                    </div>
                    <div style={{ backgroundColor: '#fff2f0', border: '1px solid #ffccc7', borderRadius: '4px', padding: '12px', margin: '12px 0' }}>
                        <p style={{ margin: '0 0 8px 0', fontWeight: 'bold', color: '#ff4d4f' }}>
                            ⚠️ Warning: This action will:
                        </p>
                        <ul style={{ margin: 0, paddingLeft: '16px', fontSize: '12px' }}>
                            <li>Delete all associated projects under these programs</li>
                            <li>Delete the programs themselves</li>
                        </ul>
                    </div>
                    <p style={{ color: '#ff4d4f', fontSize: '12px', marginBottom: 0 }}>
                        This action cannot be undone. Make sure you have backups if needed.
                    </p>
                    
                    {/* Progress Indicator */}
                    {this.state.deleteProgress.show && (
                        <div style={{ 
                            marginTop: '15px', 
                            padding: '12px', 
                            backgroundColor: '#f6f8fa', 
                            border: '1px solid #d1d9e0', 
                            borderRadius: '4px' 
                        }}>
                            <div style={{ display: 'flex', alignItems: 'center', marginBottom: '8px' }}>
                                <Icon type="loading" style={{ marginRight: '8px', color: '#1890ff' }} />
                                <span style={{ fontWeight: 'bold', fontSize: '14px' }}>
                                    Deleting Programs ({this.state.deleteProgress.completed}/{this.state.deleteProgress.total})
                                </span>
                            </div>
                            
                            <div style={{ 
                                width: '100%', 
                                height: '8px', 
                                backgroundColor: '#e6f4ff', 
                                borderRadius: '4px', 
                                marginBottom: '8px' 
                            }}>
                                <div style={{ 
                                    width: `${(this.state.deleteProgress.completed / this.state.deleteProgress.total) * 100}%`, 
                                    height: '100%', 
                                    backgroundColor: '#1890ff', 
                                    borderRadius: '4px',
                                    transition: 'width 0.3s ease'
                                }} />
                            </div>
                            
                            <div style={{ fontSize: '12px', color: '#666' }}>
                                <div><strong>Current:</strong> {this.state.deleteProgress.currentProgram}</div>
                                <div><strong>Step:</strong> {this.state.deleteProgress.currentStep}</div>
                            </div>
                            
                            {this.state.deleteProgress.details.length > 0 && (
                                <div style={{ 
                                    maxHeight: '100px', 
                                    overflowY: 'auto', 
                                    marginTop: '8px',
                                    fontSize: '11px',
                                    backgroundColor: '#fff',
                                    padding: '6px',
                                    borderRadius: '2px',
                                    border: '1px solid #e6e6e6'
                                }}>
                                    {this.state.deleteProgress.details.slice(-5).map((detail, index) => (
                                        <div key={index} style={{ marginBottom: '2px', color: '#666' }}>
                                            {detail}
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                </div>
            ),
            okText: `Delete ${selectedProgramIds.length} Program(s)`,
            okType: 'danger',
            cancelText: 'Cancel',
            width: 600,
            onOk: () => {
                return this.deleteSelectedPrograms();
            },
        });
    };

    deleteSelectedPrograms = async () => {
        const { selectedProgramIds } = this.state;
        this.setState({ isDeleting: true });

        // Initialize progress
        this.updateDeleteProgress({
            show: true,
            currentStep: 'Starting deletion process...',
            currentProgram: '',
            completed: 0,
            total: selectedProgramIds.length,
            details: []
        });

        const results = {
            successful: [],
            failed: []
        };

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            // Delete each program
            this.updateDeleteProgress({ currentStep: 'Deleting programs...' });
            this.addProgressDetail('Starting program deletion');
            
            for (const programId of selectedProgramIds) {
                const program = this.state.programs.find(p => p.id === programId);
                
                this.updateDeleteProgress({ 
                    currentProgram: program ? program.displayName : programId,
                    currentStep: 'Deleting program...'
                });

                try {
                    console.log(`Attempting to delete program: ${programId}`);
                    await api.delete(`organisationUnits/${programId}`);
                    results.successful.push(programId);
                    this.updateDeleteProgress({ completed: results.successful.length });
                    this.addProgressDetail(`✓ ${program ? program.displayName : programId} deleted successfully`);
                    console.log(`Program ${programId} deleted successfully`);
                } catch (error) {
                    console.error(`Delete failed for ${programId}:`, error);
                    results.failed.push({
                        id: programId,
                        name: program ? program.displayName : programId,
                        error: error.message || 'Unknown error'
                    });
                    this.addProgressDetail(`✗ ${program ? program.displayName : programId} failed: ${error.message || 'Unknown error'}`);
                }
            }

            // Remove successfully deleted programs from state
            const updatedPrograms = this.state.programs.filter(
                program => !results.successful.includes(program.id)
            );
            const updatedFilteredPrograms = this.state.filteredPrograms.filter(
                program => !results.successful.includes(program.id)
            );

            this.setState({
                programs: updatedPrograms,
                filteredPrograms: updatedFilteredPrograms,
                selectedProgramIds: [],
                isDeleting: false,
                deleteProgress: {
                    show: false,
                    currentStep: '',
                    currentProgram: '',
                    completed: 0,
                    total: 0,
                    details: []
                }
            });

            // Show appropriate messages
            if (results.successful.length > 0 && results.failed.length === 0) {
                message.success(`Successfully deleted ${results.successful.length} program(s)`);
            } else if (results.successful.length > 0 && results.failed.length > 0) {
                Modal.info({
                    title: 'Partial Success',
                    content: (
                        <div>
                            <p><strong>Successfully deleted:</strong> {results.successful.length} program(s)</p>
                            <p><strong>Failed to delete:</strong> {results.failed.length} program(s)</p>
                            <div style={{ maxHeight: '150px', overflowY: 'auto', marginTop: '10px' }}>
                                {results.failed.map(failure => (
                                    <div key={failure.id} style={{ padding: '2px 0', fontSize: '12px', color: '#ff4d4f' }}>
                                        • {failure.name}: {failure.error}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ),
                    width: 600,
                });
            } else if (results.failed.length > 0) {
                Modal.error({
                    title: 'Delete Failed',
                    content: (
                        <div>
                            <p>Failed to delete selected programs:</p>
                            <div style={{ maxHeight: '150px', overflowY: 'auto', marginTop: '10px' }}>
                                {results.failed.map(failure => (
                                    <div key={failure.id} style={{ padding: '2px 0', fontSize: '12px' }}>
                                        • {failure.name}: {failure.error}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ),
                    width: 600,
                });
            }
        } catch (error) {
            console.error('Error during bulk delete:', error);
            this.setState({ 
                isDeleting: false,
                deleteProgress: {
                    show: false,
                    currentStep: '',
                    currentProgram: '',
                    completed: 0,
                    total: 0,
                    details: []
                }
            });

            Modal.error({
                title: 'Bulk Delete Failed',
                content: `Unexpected error occurred: ${error.message}`,
            });
        }
    };

    handleSearch = (value) => {
        const { programs } = this.state;

        if (!value.trim()) {
            this.setState({
                searchValue: value,
                filteredPrograms: programs
            });
            return;
        }

        const searchTerm = value.toLowerCase();
        const filteredPrograms = programs.filter(program => {
            // Search in program name, ID
            const programMatches = program.displayName.toLowerCase().includes(searchTerm) ||
                program.id.toLowerCase().includes(searchTerm)

            // Search in parent thematic area
            const thematicAreaMatches = program.parent &&
                program.parent.displayName.toLowerCase().includes(searchTerm);

            // Search in grandparent (if exists)
            const grandParentMatches = program.parent && program.parent.parent &&
                program.parent.parent.displayName.toLowerCase().includes(searchTerm);

            return programMatches || thematicAreaMatches || grandParentMatches;
        });

        this.setState({
            searchValue: value,
            filteredPrograms: filteredPrograms
        });
    };

    render() {
        const { programs, loading, error, searchValue, filteredPrograms, selectedProgramIds, isDeleting, refreshing } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '1200px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading programs...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchPrograms}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        const columns = [
            {
                title: 'Program Name',
                dataIndex: 'displayName',
                key: 'displayName',
                render: (text, program) => {
                    let displayText = text;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (text.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = text.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="project" style={{ color: '#fa8c16', marginRight: '8px', fontSize: '16px' }} />
                            <span
                                style={{ fontWeight: '500', fontSize: '16px' }}
                                dangerouslySetInnerHTML={{ __html: displayText }}
                            />
                        </div>
                    );
                }
            },
            {
                title: 'Thematic Area',
                dataIndex: 'parent',
                key: 'parent',
                render: (parent) => {
                    if (!parent) {
                        return <span style={{ color: '#999', fontStyle: 'italic' }}>No thematic area</span>;
                    }

                    let displayText = parent.displayName;
                    if (searchValue && searchValue.trim()) {
                        const searchTerm = searchValue.toLowerCase();
                        if (parent.displayName.toLowerCase().includes(searchTerm)) {
                            const regex = new RegExp(`(${searchValue})`, 'gi');
                            displayText = parent.displayName.replace(regex, '<mark>$1</mark>');
                        }
                    }

                    return (
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <Icon type="folder" style={{ color: '#1890ff', marginRight: '8px' }} />
                            <span dangerouslySetInnerHTML={{ __html: displayText }} />
                        </div>
                    );
                }
            },
            {
                title: 'Created Date',
                dataIndex: 'openingDate',
                key: 'openingDate',
                width: 120,
                render: (date) => {
                    if (!date) return <span style={{ color: '#999', fontStyle: 'italic' }}>Unknown</span>;
                    return new Date(date).toLocaleDateString();
                }
            },
            {
                title: 'Actions',
                key: 'actions',
                width: 120,
                render: (text, program) => (
                    <Dropdown
                        overlay={this.getProgramActionsMenu(program)}
                        trigger={['click']}
                        placement="bottomRight"
                    >
                        <Button size="small" icon="more">
                        </Button>
                    </Dropdown>
                )
            }
        ];

        const dataSource = searchValue ? filteredPrograms : programs;

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Programs
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Manage all programs
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Table Content */}
                    <div style={{ padding: '0 24px 24px 24px' }}>
                        {programs.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '60px 0', color: '#999' }}>
                                <Icon type="project" style={{ fontSize: '64px', color: '#d9d9d9', marginBottom: '16px' }} />
                                <div style={{ fontSize: '16px' }}>No programs found</div>
                                <div style={{ fontSize: '14px', marginTop: '8px' }}>
                                    <Button type="primary" onClick={this.handleCreateProgram} style={{ marginTop: '16px' }}>
                                        <Icon type="plus" />
                                        Create Your First Program
                                    </Button>
                                </div>
                            </div>
                        ) : (
                            <div>
                                <div style={{ display: 'flex', alignItems: 'center', marginBottom: 16, gap: 16 }}>
                                    <Search
                                        placeholder="Search programs by name or thematic area"
                                        value={searchValue}
                                        onChange={(e) => this.handleSearch(e.target.value)}
                                        style={{ width: 500 }}
                                    />
                                    <Button
                                        icon={refreshing ? "loading" : "reload"}
                                        onClick={this.handleRefresh}
                                        disabled={refreshing || isDeleting}
                                        title="Refresh programs"
                                    >
                                        {refreshing ? 'Refreshing...' : 'Refresh'}
                                    </Button>
                                    {selectedProgramIds.length > 0 && (
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                            <span style={{ color: '#666', fontSize: '14px' }}>
                                                {selectedProgramIds.length} selected
                                            </span>
                                            <Button
                                                size="small"
                                                onClick={this.handleSelectAll}
                                                disabled={isDeleting || refreshing}
                                            >
                                                Select All
                                            </Button>
                                            <Button
                                                size="small"
                                                onClick={this.handleClearSelection}
                                                disabled={isDeleting || refreshing}
                                            >
                                                Clear
                                            </Button>
                                            <Button
                                                type="danger"
                                                size="small"
                                                icon={isDeleting ? "loading" : "delete"}
                                                onClick={this.handleBulkDelete}
                                                disabled={isDeleting}
                                                loading={isDeleting}
                                            >
                                                {isDeleting ? 'Deleting...' : 'Delete Selected'}
                                            </Button>
                                        </div>
                                    )}
                                </div>
                                {searchValue && (
                                    <div style={{ marginBottom: 16, color: '#666', fontSize: '14px' }}>
                                        <Icon type="search" style={{ marginRight: '4px' }} />
                                        Found {dataSource.length} program(s) for "{searchValue}"
                                    </div>
                                )}
                                <Table
                                    columns={columns}
                                    dataSource={dataSource}
                                    rowKey="id"
                                    rowSelection={{
                                        selectedRowKeys: selectedProgramIds,
                                        onChange: this.handleRowSelection,
                                        getCheckboxProps: () => ({
                                            disabled: isDeleting || refreshing,
                                        }),
                                    }}
                                    pagination={{
                                        pageSize: 10,
                                        showSizeChanger: true,
                                        showQuickJumper: true,
                                        showTotal: (total, range) =>
                                            `${range[0]}-${range[1]} of ${total} ${searchValue ? 'filtered' : ''} programs`,
                                    }}
                                    size="middle"
                                />
                            </div>
                        )}
                    </div>
                </Card>

                {/* Floating Add Button */}
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    zIndex: 1000
                }}>
                    <Button
                        type="primary"
                        size="large"
                        shape="circle"
                        icon="plus"
                        onClick={this.handleCreateProgram}
                        style={{
                            width: '56px',
                            height: '56px',
                            fontSize: '20px',
                            boxShadow: '0 4px 12px rgba(24, 144, 255, 0.3)',
                            border: 'none'
                        }}
                        title="Add New Program"
                    />
                </div>
            </div>
        );
    }
}

ProgramsHierarchyList.contextTypes = {
    d2: PropTypes.object
};

export default ProgramsHierarchyList;



